    """An exact half-first-plane-intercept step; not a sampled epsilon ladder."""
    d = mul(n, F(-1))
    steps = []
    for m, o in planes:
        den = dot(m, d)
        num = dot(m, sub(o, p))
        if den and num / den > 0:
            steps.append(num / den)
    t = min(steps) / 2 if steps else F(1)
    return add(p, mul(d, t))

